SELECT id, name, email, country, is_active, credit_limit, LEAD(age) OVER w_running AS next_age, LAG(age) OVER w_running AS prev_age, LEAD(credit_limit) OVER w_running AS next_credit_limit, LAG(credit_limit) OVER w_running AS prev_credit_limit, ROW_NUMBER() OVER w_running AS row_seq, AVG(age) OVER (ORDER BY signup_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS age_avg_2 FROM customers WHERE MONTH(signup_date) IN (1, 4, 7) WINDOW w_running AS (PARTITION BY city ORDER BY signup_date, id);
